def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    # Fix for issue #8557 on Windows
    if cmd[0].startswith('/'):
        cmd[0] = cmd[0].lstrip('/')

    # Fix for issue with Windows not parsing shebangs
    if cmd[0].startswith('#!'):
        cmd[0] = cmd[0].lstrip('#!')

    # Make deep-path shebangs work just fine
    if cmd[0].startswith('!'):
        cmd[0] = cmd[0].lstrip('!')

    return cmd

