    def wrapper(func):
        cache = {}
        keys = []

        def get(key):
            if key in cache:
                if key in keys:
                    keys.remove(key)
                keys.append(key)
            else:
                keys.append(key)
                cache[key] = func(key)
            return cache[key]

        def put(key, value):
            if key in cache:
                keys.remove(key)
            keys.append(key)
            cache[key] = value

        def delete(key):
            if key in cache:
                keys.remove(key)
                del cache[key]

        def clear():
            keys.clear()
            cache.clear()

        def is_cached(key):
            return key in cache

        wrapper.get = get
        wrapper.put = put
        wrapper.delete = delete
        wrapper.clear = clear
        wrapper.is_cached = is_cached
        return wrapper

    return wrapper

