def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if arg.operator == "&":
            left, right = arg.operands
            if left.operator == "|" and right == left.operands[1]:
                new_args.append(left.operands[0])
            elif right.operator == "|" and left == right.operands[1]:
                new_args.append(right.operands[0])
        elif arg.operator == "|":
            left, right = arg.operands
            if left.operator == "~" and left.operands[0] == right:
                new_args.append(left)
            elif right.operator == "~" and right.operands[0] == left:
                new_args.append(right)
        else:
            new_args.append(arg)
    return new_args

