    def wrapper(*args, **kwargs):
        # raises error if VCS does not exist
        if vcs not in VCS.list_all():
            raise ValueError(f"The specified VCS '{vcs}' does not exist")

        # raises error if method is not a valid handler
        if not callable(method):
